create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade, first_name text, business_name text, trade text, city text, radius_minutes int default 90, created_at timestamptz default now());
create table if not exists prospects(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,project text,value numeric default 0,score int,status text default 'Nouveau',phone text,email text,notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists jobs(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,title text not null,type text,city text,travel_minutes int,budget_min numeric,budget_max numeric,score int,urgency text,source text,description text,is_demo boolean default false,created_at timestamptz default now());
create table if not exists reminders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,prospect_id uuid references prospects(id) on delete cascade,title text not null,due_at timestamptz,status text default 'pending',created_at timestamptz default now());
create table if not exists quotes(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,prospect_id uuid references prospects(id) on delete set null,title text,status text default 'draft',disclaimer text default 'Estimation indicative nécessitant une vérification par un professionnel.',total numeric default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists quote_items(id uuid primary key default gen_random_uuid(),quote_id uuid not null references quotes(id) on delete cascade,label text not null,quantity numeric,unit text,unit_price numeric,sort_order int default 0);
create table if not exists job_analyses(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,prospect_id uuid references prospects(id) on delete set null,type text,detected_items jsonb default '[]',hypotheses jsonb default '[]',missing_info jsonb default '[]',complexity text,notes text,created_at timestamptz default now());
alter table profiles enable row level security; alter table prospects enable row level security; alter table jobs enable row level security; alter table reminders enable row level security; alter table quotes enable row level security; alter table quote_items enable row level security; alter table job_analyses enable row level security;
create policy "profiles own" on profiles for all using(auth.uid()=id) with check(auth.uid()=id);
create policy "prospects own" on prospects for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "jobs own or demo" on jobs for all using(auth.uid()=user_id or (user_id is null and is_demo=true)) with check(auth.uid()=user_id or (user_id is null and is_demo=true));
create policy "reminders own" on reminders for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "quotes own" on quotes for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "quote items own" on quote_items for all using(exists(select 1 from quotes q where q.id=quote_id and q.user_id=auth.uid())) with check(exists(select 1 from quotes q where q.id=quote_id and q.user_id=auth.uid()));
create policy "analyses own" on job_analyses for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
